<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {useAuth} from '../../entities/auth/model'
import {request,query,errorMessage,isCancelled} from '../../shared/api/client'
import type {Dashboard,CallList,Taxonomy,Filter} from '../../shared/interfaces'
import {shortDate,percent} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Empty from '../../shared/ui/Empty.vue'
import Notice from '../../shared/ui/Notice.vue'
import CallFilters from '../../features/filter-builder/CallFilters.vue'
import CallActionSidebar from '../../features/call-actions/CallActionSidebar.vue'
import {emptyFilter,validateFilter} from '../../shared/lib/filter'
import CallTable from '../../features/call-table/CallTable.vue'
const auth=useAuth(),router=useRouter(),data=ref<Dashboard|null>(null),recent=ref<CallList|null>(null),taxonomy=ref<Taxonomy>({tags:[],statuses:[]}),loading=ref(true),error=ref(''),range=ref('30'),from=ref(''),to=ref(''),workspaceFilter=ref<Filter>(emptyFilter()),actionCall=ref(''),applied=ref<{from:string;to:string;filter:Filter}|null>(null)
let timer:ReturnType<typeof setInterval>|undefined
const chartMax=computed(()=>Math.max(1,...(data.value?.daily.map(d=>d.calls)||[])))
const employeeMax=computed(()=>Math.max(1,...(data.value?.employees.map(d=>d.calls)||[])))
function dates(){if(range.value==='custom')return{from:from.value,to:to.value};const now=new Date(),start=new Date(now);start.setDate(start.getDate()-Number(range.value));return{from:start.toISOString(),to:now.toISOString()}}
async function load(background=false){if(!background)loading.value=true;error.value='';try{const params=background&&applied.value?applied.value:{...dates(),filter:validateFilter(workspaceFilter.value)};const[d,r,t]=await Promise.all([request<Dashboard>('/dashboard'+query(params)),request<CallList>('/calls'+query({...params,limit:25})),request<Taxonomy>('/taxonomy')]);data.value=d;recent.value=r;taxonomy.value=t;applied.value={...params,filter:JSON.parse(JSON.stringify(params.filter))}}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
function drill(field?:string,value?:unknown){const snapshot=applied.value||{...dates(),filter:emptyFilter()};const filter:Filter={op:'and',rules:[snapshot.filter,...(field?[{field,op:Array.isArray(value)?'in':'eq',value} as Filter]:[])]};router.push({path:'/calls',query:{from:snapshot.from,to:snapshot.to,filter:JSON.stringify(filter)}})}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true)},30000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">Всё важное перед глазами</span><h1>Обзор звонков</h1><p>Как команда общается с клиентами и какие обращения требуют внимания.</p></div><div class="heading-actions"><select v-model="range" aria-label="Период аналитики" @change="load()"><option value="7">Последние 7 дней</option><option value="30">Последние 30 дней</option><option value="90">Последние 90 дней</option><option value="custom">Выбрать период</option></select><template v-if="range==='custom'"><input v-model="from" type="date" aria-label="Начало периода" @change="load()"/><input v-model="to" type="date" aria-label="Конец периода" @change="load()"/></template><button class="button" @click="load()"><Icon name="refresh" :size="15"/>Обновить</button></div></div><Notice :message="error" kind="error"/><Notice v-if="data&&!data.coverage.complete" :message="data.coverage.reason||'История загружена частично: показатели отражают доступные звонки.'"/>
<div class="card dashboard-filters"><CallFilters v-model="workspaceFilter" :taxonomy="taxonomy"/><div class="form-actions"><button class="button primary small" @click="load()">Применить фильтры</button></div></div><Empty v-if="loading&&!data" loading/>
<template v-else-if="data"><div class="stat-grid"><button class="card stat-card" @click="drill()"><div class="stat-top"><span>Всего звонков</span><span class="stat-icon"><Icon name="phone" :size="16"/></span></div><div class="stat-value">{{data.totals.calls.toLocaleString('ru-RU')}}</div><div class="stat-bottom">Все направления за выбранный период</div></button><button class="card stat-card" @click="drill('human_connected',true)"><div class="stat-top"><span>Состоявшиеся разговоры</span><span class="stat-icon"><Icon name="check" :size="16"/></span></div><div class="stat-value">{{data.totals.answered.toLocaleString('ru-RU')}}</div><div class="stat-bottom"><strong>{{percent(data.totals.answered,data.totals.calls)}}%</strong> от всех звонков</div></button><button class="card stat-card warn" @click="drill('callback_state',['open','overdue'])"><div class="stat-top"><span>Ждут обработки</span><span class="stat-icon"><Icon name="clock" :size="16"/></span></div><div class="stat-value">{{data.totals.unhandled}}</div><div class="stat-bottom">Просрочено: {{data.totals.overdue}} · требуется внимание</div></button><button class="card stat-card teal" @click="drill('analysis_state',['analyzed','partial'])"><div class="stat-top"><span>Средняя оценка диалога</span><span class="stat-icon"><Icon name="activity" :size="16"/></span></div><div class="stat-value">{{data.totals.average_score===null?'—':Math.round(data.totals.average_score)}}<span style="font-size:14px;font-weight:400;color:#a4d0c7"> / 100</span></div><div class="stat-bottom">Проанализировано разговоров: {{data.totals.analyzed}}</div></button></div>
<div class="grid-two"><div class="card"><div class="card-header"><div><h3>Динамика обращений</h3><p>Всего звонков и пропущенные по дням</p></div><span class="badge outline">{{data.daily.length}} дней</span></div><div v-if="data.daily.length" class="chart-area"><div class="chart-bars" role="img" aria-label="График количества звонков по дням"><div v-for="day in data.daily" :key="day.date" class="chart-bar-wrap"><div class="chart-bar" :style="{height:`${Math.max(day.calls?3:0,day.calls/chartMax*100)}%`}" :title="`${shortDate(day.date)}: ${day.calls} звонков, ${day.missed} пропущенных`"><i class="missed-segment" :style="{height:`${percent(day.missed,day.calls)}%`}"></i></div></div></div><div class="chart-labels"><span>{{shortDate(data.daily[0]!.date)}}</span><span>{{shortDate(data.daily[Math.floor(data.daily.length/2)]!.date)}}</span><span>{{shortDate(data.daily[data.daily.length-1]!.date)}}</span></div><div class="chart-legend"><span><i class="legend-dot"></i>Все звонки</span><span><i class="legend-dot amber"></i>Пропущенные</span></div></div><Empty v-else title="Нет данных за период" description="Динамика появится после импорта звонков."/></div>
<div class="card"><div class="card-header"><div><h3>Команда в диалогах</h3><p>Объём звонков и качество общения</p></div><Icon name="user" :size="16" style="color:#a4b6b1"/></div><div v-if="data.employees.length" class="card-body" style="padding-top:5px;padding-bottom:5px"><div v-for="(employee,i) in data.employees.slice(0,5)" :key="employee.name" class="employee-row"><span class="avatar small" :style="{background:['#e6efe5','#e7edf3','#f4ebdd','#e9e7f2','#e0efed'][i]}">{{employee.name.slice(0,1)||'?'}}</span><div class="employee-info"><b>{{employee.name||'Без сотрудника'}}</b><small>{{employee.calls}} звонков</small><div class="progress-track"><i :style="{width:`${employee.calls/employeeMax*100}%`}"></i></div></div><span class="score" :class="employee.average_score===null?'unknown':employee.average_score<75?'medium':''">{{employee.average_score===null?'—':Math.round(employee.average_score)}}</span></div></div><Empty v-else title="Сотрудники ещё не определены" description="Сопоставьте добавочные Телфина с участниками команды."/></div></div>
<div class="card"><div class="card-header"><div><h3>Последние звонки</h3><p>До 25 последних обращений в выбранной выборке</p></div><button class="text-link" @click="drill()">Все звонки выборки →</button></div><CallTable v-if="recent?.items.length" @manage="actionCall=$event" :calls="recent.items" :taxonomy="taxonomy" :timezone="auth.me?.organization.timezone"/><Empty v-else title="История пока пуста" description="Подключите Телфин в настройках и запустите загрузку звонков."><RouterLink v-if="auth.isOwner" class="button primary" to="/settings/telphin">Настроить подключение</RouterLink></Empty></div>
</template><Empty v-else title="Обзор недоступен" description="Не удалось получить данные сервера."><button class="button" @click="load()">Повторить</button></Empty><CallActionSidebar v-if="actionCall" :key="actionCall" :call-id="actionCall" @close="actionCall=''" @saved="load(true)"/></template>
